const CACHE="oro-network-map-20261102-activity-log-v45";
const SHELL=["/network-olt.js","/network-olt.css","/map-selection.js","/olt/index.json","/manifest.webmanifest","/vendor/leaflet/leaflet.css","/vendor/leaflet/leaflet.js","/layers.json","/incident-photos.json.gz","/admin.html","/icons/icon-192.png","/icons/icon-512.png"];
self.addEventListener("install",event=>event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(SHELL)).then(()=>self.skipWaiting())));
self.addEventListener("activate",event=>event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(key=>key!==CACHE).map(key=>caches.delete(key)))).then(()=>self.clients.claim()).then(()=>self.clients.matchAll({type:"window"})).then(clients=>Promise.all(clients.map(client=>{const url=new URL(client.url);if(url.searchParams.get("_sw")==="45")return;url.searchParams.set("_sw","45");return client.navigate(url.href)})))));
self.addEventListener("fetch",event=>{if(event.request.method!=="GET")return;const url=new URL(event.request.url);if(url.pathname.startsWith("/api/")||url.pathname.startsWith("/cdn-cgi/"))return;event.respondWith(fetch(event.request).then(response=>{if(response.ok&&url.origin===self.location.origin){const copy=response.clone();caches.open(CACHE).then(cache=>cache.put(event.request,copy))}return response}).catch(()=>caches.match(event.request))) });
